// === Tab: mySketch ===
var Ox = 0; // Origin
var Oy = 0;
var x = 0;
var r = false;
var t = 0; // T for 'tab'     :)
var tabd= false;
var col = 255;
var w = 20;

var c = [randomColor(), randomColor(), randomColor(), randomColor(), randomColor(), randomColor(), randomColor()];

function setup() {
  createCanvas(windowWidth, windowHeight);
  frameRate(60); // The faster it is, the bigger the blur is (it's because get() and image() can't keep up)
  noStroke();
  background(28);

  Ox = width/24;
  Oy = height-w*3;

  x = Ox;
}

function draw() {

  r = (random()>0.75 && r==false);

  // Color
  if (random()<0.2 && r) col = color(random(c))
  else if (r) col = 255;

  if (tabd) fill("#FFC93C")
  else fill(col);

  if (x==Ox) {
    rect(Ox+t*w-w*tabd, Oy, w, w, 30);
  }else{

    if (r) x+=w/2
    else rect(x-w+t*w-w*tabd,Oy, w+w, w, 30);

  }

  x+=w;

  if ((random() < 0.15 && x>=5*w+t*w) || x>=width-w*3) { // New line

    if (tabd) tabd = false;

    translate(0, -(4*w/3));
    const g = get(0, 0, width, height);
    image(g, 0, 0, width, height);
    x=Ox;

    if (random()<0.3) {
      tabd = true;
      t++;
      x=Ox;
    }else if ((random()<0.4 || t>=6) && t>0) t--;

  }

}
